function meteor() { const r = rng(9), d = 4.2, b = mk(d), f = new Bq('bp', 400, 0.8), g = new Bq('lp', 90, 0.8); for (let i = 0; i < b.length; i++) { const t = i / SR, p = t / d, x = r() * 2 - 1; if ((i & 31) === 0) f.set(300 + 3500 * Math.pow(p, 2), 0.8); b[i] = (f.p(x) * 1.2 + g.p(x) * 2) * Math.pow(p, 1.5) * (1 - 0.15 * p); } mix(b, boom(5, 1.6), 3.3, 1.0); return norm(b, 0.95); }
