    const lg = new THREE.Group(); lg.position.set((0.8 - i * 0.55) * k, 1.0 * k, sd * 0.75 * k); lg.rotation.y = sd * (-PI / 2 + (i - 1.5) * 0.35); rig.frame.add(lg);
