    const boneC = hx(mixHex(0xd8c8a0, pal.side, 0.12)), beakC = hx(0x2c241d), beakC2 = hx(0x5a4a3a), clawC = hx(0x2a231d), hornB = hx(0x8a7658), hornT = hx(0xe2d6b6);
