    g.fillStyle = o.color || '#ffffff'; g.fillText(label, 160, o.sub ? 28 : 40);
    if (o.sub) { g.font = 'bold 24px system-ui, sans-serif'; g.strokeText(o.sub, 160, 60); g.fillStyle = '#ffd35a'; g.fillText(o.sub, 160, 60); }
