    jawKeys: SK([[0.75, 0.78, .14, .3, .56, 2.2], [1.3, 0.76, .12, .22, .46], [1.62, 0.8, .05, .08, .2], [1.7, 0.81, .005, .005, .005]]),
    flukeX: -1.75, flukeK: 1.3, dorsalX: -0.6, dorsalK: 0.7, frontX: 0.2, hindX: -0.6, flipK: 0.9,
