  leaves.customDepthMaterial = windify(new T.MeshDepthMaterial({ depthPacking: T.RGBADepthPacking, map: tex[P.leaf], alphaTest: 0.5 }), P.wind, 0.012);
  leaves.castShadow = leaves.receiveShadow = true;
