  const quad = new T.PlaneGeometry(0.5, 1, 1, 1); quad.translate(0, 0.5, 0);
  { const p = quad.attributes.position; for (let i = 0; i < p.count; i++) { const y = p.getY(i); p.setZ(i, -y * y * 0.08); } quad.computeVertexNormals(); }
